rimero multiplica 2 por x. Revisa la tabla, comprueba los puntos y vuelve a entregar.","actualizado_en":"@fecha:0:11:5@"}],"planes":[{"estudiante_id":"00000000-0000-4000-8000-000000000011","semana_inicio":"@dia:0@","bloques":[{"id":"demo-b1","tarea_id":"00000000-0000-4000-8000-000000000204","titulo":"Repasar: Ley de Ohm","inicio":"@fecha:0:15:0@","fin":"@fecha:0:15:30@","estado":"planificado"},{"id":"demo-b2","tarea_id":"00000000-0000-4000-8000-000000000205","titulo":"Practicar: Razón y proporción","inicio":"@fecha:0:16:0@","fin":"@fecha:0:16:30@","estado":"planificado"},{"id":"demo-b3","tarea_id":"00000000-0000-4000-8000-000000000202","titulo":"Repasar: Mínimo común múltiplo","inicio":"@fecha:1:15:0@","fin":"@fecha:1:15:30@","estado":"planificado"},{"id":"demo-b4","tarea_id":"00000000-0000-4000-8000-000000000207","titulo":"Practicar: Variables numéricas","inicio":"@fecha:1:16:0@","fin":"@fecha:1:16:30@","estado":"planificado"},{"id":"demo-b5","tarea_id":"00000000-0000-4000-8000-000000000206","titulo":"Repasar: Primitivas 3D","inicio":"@fecha:2:15:0@","fin":"@fecha:2:15:30@","estado":"planificado"},{"id":"demo-b6","tarea_id":"00000000-0000-4000-8000-000000000208","titulo":"Practicar: Tabla de valores","inicio":"@fecha:2:16:0@","fin":"@fecha:2:16:30@","estado":"planificado"},{"id":"demo-b7","tarea_id":"00000000-0000-4000-8000-000000000203","titulo":"Repasar: Salidas digitales","inicio":"@fecha:3:15:0@","fin":"@fecha:3:15:30@","estado":"planificado"},{"id":"demo-b8","tarea_id":"00000000-0000-4000-8000-000000000201","titulo":"Practicar: Despejar x","inicio":"@fecha:3:16:0@","fin":"@fecha:3:16:30@","estado":"planificado"},{"id":"demo-b9","tarea_id":"00000000-0000-4000-8000-000000000204","titulo":"Repasar: Ley de Ohm","inicio":"@fecha:4:15:0@","fin":"@fecha:4:15:30@","estado":"planificado"},{"id":"demo-b10","tarea_id":"00000000-0000-4000-8000-000000000205","titulo":"Practicar: Razón y proporción","inicio":"@fecha:4:16:0@","fin":"@fecha:4:16:30@","estado":"planificado"},{"id":"demo-b11","tarea_id":"00000000-0000-4000-8000-000000000202","titulo":"Repasar: Mínimo común múltiplo","inicio":"@fecha:5:9:0@","fin":"@fecha:5:9:30@","estado":"planificado"},{"id":"demo-b12","tarea_id":"00000000-0000-4000-8000-000000000207","titulo":"Practicar: Variables numéricas","inicio":"@fecha:5:10:0@","fin":"@fecha:5:10:30@","estado":"planificado"},{"id":"demo-b13","tarea_id":"00000000-0000-4000-8000-000000000206","titulo":"Repasar: Primitivas 3D","inicio":"@fecha:6:15:0@","fin":"@fecha:6:15:30@","estado":"planificado"},{"id":"demo-b14","tarea_id":"00000000-0000-4000-8000-000000000208","titulo":"Practicar: Tabla de valores","inicio":"@fecha:6:16:0@","fin":"@fecha:6:16:30@","estado":"planificado"}],"avisos":["Llegó una tarea de Tecnología; reservé tiempo para practicar y comprobar las ecuaciones."],"generado_en":"@fecha:0:11:5@"},{"estudiante_id":"00000000-0000-4000-8000-000000000011","semana_inicio":"@dia:7@","bloques":[{"id":"demo-b1-proxima","tarea_id":"00000000-0000-4000-8000-000000000204","titulo":"Repasar: Ley de Ohm","inicio":"@fecha:7:15:0@","fin":"@fecha:7:15:30@","estado":"planificado"},{"id":"demo-b2-proxima","tarea_id":"00000000-0000-4000-8000-000000000205","titulo":"Practicar: Razón y proporción","inicio":"@fecha:7:16:0@","fin":"@fecha:7:16:30@","estado":"planificado"},{"id":"demo-b3-proxima","tarea_id":"00000000-0000-4000-8000-000000000202","titulo":"Repasar: Mínimo común múltiplo","inicio":"@fecha:8:15:0@","fin":"@fecha:8:15:30@","estado":"planificado"},{"id":"demo-b4-proxima","tarea_id":"00000000-0000-4000-8000-000000000207","titulo":"Practicar: Variables numéricas","inicio":"@fecha:8:16:0@","fin":"@fecha:8:16:30@","estado":"planificado"},{"id":"demo-b5-proxima","tarea_id":"00000000-0000-4000-8000-000000000206","titulo":"Repasar: Primitivas 3D","inicio":"@fecha:9:15:0@","fin":"@fecha:9:15:30@","estado":"planificado"},{"id":"demo-b6-proxima","tarea_id":"00000000-0000-4000-8000-000000000208","titulo":"Practicar: Tabla de valores","inicio":"@fecha:9:16:0@","fin":"@fecha:9:16:30@","estado":"planificado"},{"id":"demo-b7-proxima","tarea_id":"00000000-0000-4000-8000-000000000203","titulo":"Repasar: Salidas digitales","inicio":"@fecha:10:15:0@","fin":"@fecha:10:15:30@","estado":"planificado"},{"id":"demo-b8-proxima","tarea_id":"00000000-0000-4000-8000-000000000201","titulo":"Practicar: Despejar x","inicio":"@fecha:10:16:0@","fin":"@fecha:10:16:30@","estado":"planificado"},{"id":"demo-b9-proxima","tarea_id":"00000000-0000-4000-8000-000000000204","titulo":"Repasar: Ley de Ohm","inicio":"@fecha:11:15:0@","fin":"@fecha:11:15:30@","estado":"planificado"},{"id":"demo-b10-proxima","tarea_id":"00000000-0000-4000-8000-000000000205","titulo":"Practicar: Razón y proporción","inicio":"@fecha:11:16:0@","fin":"@fecha:11:16:30@","estado":"planificado"},{"id":"demo-b11-proxima","tarea_id":"00000000-0000-4000-8000-000000000202","titulo":"Repasar: Mínimo común múltiplo","inicio":"@fecha:12:9:0@","fin":"@fecha:12:9:30@","estado":"planificado"},{"id":"demo-b12-proxima","tarea_id":"00000000-0000-4000-8000-000000000207","titulo":"Practicar: Variables numéricas","inicio":"@fecha:12:10:0@","fin":"@fecha:12:10:30@","estado":"planificado"},{"id":"demo-b13-proxima","tarea_id":"00000000-0000-4000-8000-000000000206","titulo":"Repasar: Primitivas 3D","inicio":"@fecha:13:15:0@","fin":"@fecha:13:15:30@","estado":"planificado"},{"id":"demo-b14-proxima","tarea_id":"00000000-0000-4000-8000-000000000208","titulo":"Practicar: Tabla de valores","inicio":"@fecha:13:16:0@","fin":"@fecha:13:16:30@","estado":"planificado"}],"avisos":["Llegó una tarea de Tecnología; reservé tiempo para practicar y comprobar las ecuaciones."],"generado_en":"@fecha:0:11:5@"}],"preferencias":[{"estudiante_id":"00000000-0000-4000-8000-000000000011","horas_disponibles":[{"dia":1,"desde":"15:00","hasta":"18:00"},{"dia":2,"desde":"15:00","hasta":"18:00"},{"dia":3,"desde":"15:00","hasta":"18:00"},{"dia":4,"desde":"15:00","hasta":"18:00"},{"dia":5,"desde":"15:00","hasta":"18:00"},{"dia":0,"desde":"15:00","hasta":"18:00"},{"dia":6,"desde":"09:00","hasta":"12:00"}],"max_minutos_bloque":45}]}';
  coincidencia text[];
  lunes date := date_trunc('week', current_date)::date;
  fila jsonb;
begin
  -- Aborta antes de escribir si una cuenta falta o un ID pertenece a otra persona.
  for fila in select value from jsonb_array_elements('[{"id":"00000000-0000-4000-8000-000000000001","rol":"docente","nombre":"Prof. Ana Rodríguez","idioma":"es","correo":"docente@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000011","rol":"estudiante","nombre":"Camila Pérez","idioma":"es","correo":"camila@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000012","rol":"estudiante","nombre":"Luis Martínez","idioma":"es","correo":"luis@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000013","rol":"estudiante","nombre":"Sofía Gómez","idioma":"es","correo":"sofia@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000014","rol":"estudiante","nombre":"Diego Fernández","idioma":"es","correo":"diego@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000015","rol":"estudiante","nombre":"Valeria Santos","idioma":"es","correo":"valeria@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000016","rol":"estudiante","nombre":"Yandel Rosario","idioma":"es","correo":"yandel@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000017","rol":"estudiante","nombre":"Alondra de la Cruz","idioma":"es","correo":"alondra@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000018","rol":"estudiante","nombre":"Dariel Jiménez","idioma":"es","correo":"dariel@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000019","rol":"estudiante","nombre":"Nayeli Tejada","idioma":"es","correo":"nayeli@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000020","rol":"estudiante","nombre":"Elian Alcántara","idioma":"es","correo":"elian@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000021","rol":"estudiante","nombre":"Kiara Peralta","idioma":"es","correo":"kiara@muselearn.demo"},{"id":"00000000-0000-4000-8000-000000000022","rol":"estudiante","nombre":"Jadiel Encarnación","idioma":"es","correo":"jadiel@muselearn.demo"}]'::jsonb) loop
    if not exists (select 1 from auth.users where id = (fila->>'id')::uuid and email = fila->>'correo' and email like '%@muselearn.demo') then
      raise exception 'Falta cuenta demo o ID ocupado: %; ejecutar seed:auth', fila->>'correo';
    end if;
  end loop;
  for coincidencia in select regexp_matches(texto, '@fecha:(-?[0-9]+):([0-9]+):([0-9]+)@', 'g') loop
    texto := replace(texto, '@fecha:' || array_to_string(coincidencia, ':') || '@',
      to_char((lunes + coincidencia[1]::int + make_time(coincidencia[2]::int, coincidencia[3]::int, 0)) at time zone 'America/Santo_Domingo' at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  end loop;
  for coincidencia in select regexp_matches(texto, '@dia:(-?[0-9]+)@', 'g') loop
    texto := replace(texto, '@dia:' || coincidencia[1] || '@', (lunes + coincidencia[1]::int)::text);
  end loop;
  datos := texto::jsonb;
  -- Las clases/tareas ya existentes deben pertenecer exclusivamente a cuentas demo.
  if exists (select 1 from clases c join jsonb_array_elements(datos->'clases') j on c.id = (j->>'id')::uuid
    where c.docente_id <> (j->>'docente_id')::uuid)
    or exists (select 1 from tareas t join jsonb_array_elements(datos->'tareas') j on t.id = (j->>'id')::uuid
      where t.clase_id <> (j->>'clase_id')::uuid) then
    raise exception 'ID de clase/tarea ocupado fuera del conjunto demo';
  end if;
  if exists (select 1 from inscripciones i join jsonb_array_elements(datos->'clases') j on i.clase_id = (j->>'id')::uuid
    where not exists (select 1 from jsonb_array_elements(datos->'cuentas') u where (u->>'id')::uuid = i.estudiante_id)) then
    raise exception 'Clase demo con estudiantes ajenos; no se modifica';
  end if;
  insert into clases select * from jsonb_populate_recordset(null::clases, datos->'clases')
    on conflict (id) do update set nombre = excluded.nombre, materia = excluded.materia, grado = excluded.grado;
  insert into inscripciones (clase_id, estudiante_id)
    select (c->>'id')::uuid, (u->>'id')::uuid from jsonb_array_elements(datos->'clases') c cross join jsonb_array_elements(datos->'cuentas') u
    where u->>'rol' = 'estudiante' on conflict do nothing;
  insert into tareas select * from jsonb_populate_recordset(null::tareas, datos->'tareas')
    on conflict (id) do update set titulo = excluded.titulo, instrucciones = excluded.instrucciones,
      fecha_entrega = excluded.fecha_entrega, competencias = excluded.competencias, nivel_ayuda = excluded.nivel_ayuda,
      modalidad = excluded.modalidad, enlace_externo = excluded.enlace_externo;
  -- Solo reinicia evidencia de estos IDs fijos y estas cuentas ficticias. Nunca borra tareas ni perfiles.
  if exists (select 1 from entregas e join jsonb_array_elements(datos->'entregas') j on e.id = (j->>'id')::uuid
    where e.estudiante_id <> (j->>'estudiante_id')::uuid or e.tarea_id <> (j->>'tarea_id')::uuid) then
    raise exception 'ID de entrega ocupado fuera del conjunto demo';
  end if;
  delete from entregas e using jsonb_array_elements(datos->'entregas') j
    where e.id = (j->>'id')::uuid and e.estudiante_id = (j->>'estudiante_id')::uuid;
  insert into entregas select * from jsonb_populate_recordset(null::entregas, datos->'entregas');
  insert into analisis_tareas (tarea_id, estudiante_id, datos)
    select (j->>'tarea_id')::uuid, (j->>'estudiante_id')::uuid, j from jsonb_array_elements(datos->'analisis') j
    on conflict (tarea_id, estudiante_id) do update set datos = excluded.datos;
  insert into sesiones_verificacion (id, entrega_id, preguntas, estado)
    select (j->>'id')::uuid, (j->>'entrega_id')::uuid, j->'preguntas', j->>'estado' from jsonb_array_elements(datos->'sesiones') j;
  insert into informes (entrega_id, informe, ruta)
    select (j->>'entrega_id')::uuid, j, (select r from jsonb_array_elements(datos->'rutas') r where r->>'entrega_id' = j->>'entrega_id')
    from jsonb_array_elements(datos->'informes') j on conflict (entrega_id) do update set informe = excluded.informe, ruta = excluded.ruta;
  insert into comentarios_entrega select * from jsonb_populate_recordset(null::comentarios_entrega, datos->'comentarios')
    on conflict (entrega_id) do update set texto = excluded.texto, actualizado_en = excluded.actualizado_en;
  insert into calificaciones select * from jsonb_populate_recordset(null::calificaciones, datos->'calificaciones')
    on conflict (entrega_id) do update set nota = excluded.nota, devuelta = excluded.devuelta, motivo_devolucion = excluded.motivo_devolucion;
  insert into preferencias_estudio (estudiante_id, datos)
    select (j->>'estudiante_id')::uuid, j from jsonb_array_elements(datos->'preferencias') j
    on conflict (estudiante_id) do update set datos = excluded.datos;
  insert into planes (estudiante_id, semana_inicio, datos)
    select (j->>'estudiante_id')::uuid, (j->>'semana_inicio')::date, j from jsonb_array_elements(datos->'planes') j
    on conflict (estudiante_id, semana_inicio) do update set datos = excluded.datos;
end $demo$;
commit;
